package com.schambeck.marketplace.usecase.order;
import com.fasterxml.jackson.databind.ObjectMapper; import com.schambeck.marketplace.exception.*; import com.schambeck.marketplace.usecase.cart.*; import com.schambeck.marketplace.usecase.cartitem.*; import com.schambeck.marketplace.usecase.inventory.InventoryService; import com.schambeck.marketplace.usecase.offer.OfferService; import com.schambeck.marketplace.usecase.user.User; import com.schambeck.marketplace.usecase.user.UserRepository; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.time.*; import java.util.*;
@Service @RequiredArgsConstructor @Transactional(readOnly=true) public class OrderService {
 private final OrderRepository orders; private final OrderItemRepository items; private final OrderStatusHistoryRepository history; private final CartRepository carts; private final CartItemRepository cartItems; private final UserRepository users; private final OfferService offers; private final InventoryService inventory; private final ObjectMapper mapper;
 @Transactional public Order checkout(String username,String key,String instructions){ if(key==null||key.isBlank()) throw new OrderValidationException("Idempotency-Key is required."); Optional<Order> existing=orders.findByBuyer_UsernameAndCheckoutKey(username,key); if(existing.isPresent()) return existing.get(); Cart cart=carts.findByUser_UsernameOrThrow(username); List<CartItem> source=cartItems.findAllByCart_IdOrderByIdDesc(cart.getId()); if(source.isEmpty()) throw new OrderValidationException("Cart is empty."); User buyer=users.findByUsernameOrThrow(username); BigDecimal total=BigDecimal.ZERO; Order order=orders.save(Order.builder().publicId(UUID.randomUUID()).buyer(buyer).cartId(cart.getId()).checkoutKey(key).status(OrderStatus.CREATED).subtotalAmount(BigDecimal.ZERO).discountTotal(BigDecimal.ZERO).taxTotal(BigDecimal.ZERO).shippingTotal(BigDecimal.ZERO).feeTotal(BigDecimal.ZERO).totalAmount(BigDecimal.ZERO).buyerSnapshot(snapshot(buyer)).instructions(instructions == null ? null : snapshot(instructions)).build()); for(CartItem c:source){ if(c.getOffer()==null) throw new OrderValidationException("Cart item has no offer."); offers.validateForCheckout(c.getOffer().getId()); BigDecimal subtotal=c.getPrice().multiply(c.getQuantity()); total=total.add(subtotal); OrderItem i=items.save(OrderItem.builder().order(order).product(c.getProduct()).offer(c.getOffer()).seller(c.getProduct().getUser()).productName(c.getProduct().getName()).productDescription(c.getProduct().getDescription()).contextGame(c.getOffer().getContextGame()).contextPlatform(c.getOffer().getContextPlatform()).contextRegion(c.getOffer().getContextRegion()).contextVariant(c.getOffer().getContextVariant()).deliveryMethod(c.getOffer().getDeliveryMethod()).unitPrice(c.getPrice()).quantity(c.getQuantity()).subtotalAmount(subtotal).snapshotVersion(1).snapshot(snapshot(c)).build()); inventory.reserve(c.getProduct().getId(),i.getId(),c.getQuantity(),"order:"+order.getPublicId()+":item:"+i.getId(),username); } order.setSubtotalAmount(total); order.setTotalAmount(total); history.save(OrderStatusHistory.builder().order(order).toStatus(OrderStatus.CREATED.name()).cause("checkout_created").source("checkout").actor(username).createdAt(LocalDateTime.now()).build()); return order; }
 private String snapshot(Object value){try{return mapper.writeValueAsString(value);}catch(Exception e){return "{}";}}
 public Order find(UUID id,String username){Order o=orders.findByPublicId(id).orElseThrow(()->new EntityNotFoundException(Order.class,id)); if(!o.getBuyer().getUsername().equals(username)) throw new OrderValidationException("Order does not belong to the authenticated buyer."); return o;}
 public Page<Order> list(String username,Pageable pageable){return orders.findAllByBuyer_UsernameOrderByCreatedAtDesc(username,pageable);}
 @Transactional public Order transition(UUID id,OrderStatus target,String cause,String source,String actor,String key){Order o=orders.findByPublicIdForUpdate(id).orElseThrow(()->new EntityNotFoundException(Order.class,id)); if(key!=null&&history.findByOrder_IdAndIdempotencyKey(o.getId(),key).isPresent()) return o; OrderStatus previous=o.getStatus(); if(!allowed(previous,target)) throw new OrderValidationException("Invalid order transition."); o.setStatus(target); history.save(OrderStatusHistory.builder().order(o).fromStatus(previous.name()).toStatus(target.name()).cause(cause).source(source).actor(actor).idempotencyKey(key).createdAt(LocalDateTime.now()).build()); return o;}
 private boolean allowed(OrderStatus from,OrderStatus to){return switch(from){case CREATED->to==OrderStatus.PAYMENT_PENDING||to==OrderStatus.CANCELLED; case PAYMENT_PENDING->to==OrderStatus.PAID||to==OrderStatus.REJECTED||to==OrderStatus.EXPIRED||to==OrderStatus.CANCELLED; case PAID->to==OrderStatus.FULFILLING||to==OrderStatus.REFUNDED||to==OrderStatus.DISPUTED; case FULFILLING->to==OrderStatus.DELIVERED||to==OrderStatus.PARTIALLY_DELIVERED||to==OrderStatus.DISPUTED; case PARTIALLY_DELIVERED->to==OrderStatus.DELIVERED; case DELIVERED->to==OrderStatus.COMPLETED||to==OrderStatus.REFUNDED||to==OrderStatus.DISPUTED; case COMPLETED->to==OrderStatus.REFUNDED||to==OrderStatus.DISPUTED; default->false;};}
}
